  const [showLogoutModal, setShowLogoutModal] = useState(false);

  // ============================================
  // VIEW ROUTER  ('login' | 'activation' | 'dashboard')
  // ============================================
  const [currentView, setCurrentView] = useState('login');

  // ============================================
  // LOGIN / OTP STATE
  // ============================================
