  const [hasMoreMatches, setHasMoreMatches] = useState(false);
  const [editProfileData, setEditProfileData] = useState({});
  const [showDescriptionModal, setShowDescriptionModal] = useState(false);
  const [descriptionData, setDescriptionData] = useState(null);

  // ============================================
  // CHAT STATE
  // ============================================
  const [chatContacts, setChatContacts] = useState([]);
  const [chatMessages, setChatMessages] = useState({});
  const [newMessage, setNewMessage] = useState('');
  const [selectedChatContact, setSelectedChatContact] = useState(null);

  // ============================================
  // STATS
  // ============================================
  const [stats, setStats] = useState({
    totalMatches: 0,
    pendingRequests: 0,
    acceptedMatches: 0,
    unreadMessages: 0
  });

  // ============================================
  // SMS SYSTEM MESSAGES - Full Flow
  // ============================================
  const SYSTEM_MESSAGES = {
    activation: `Welcome to our dating service with 6000 potential dating partners!\n\nTo register SMS start#name#age#gender#county#town to 22141.\nE.g., start#John Doe#26#Male#Nakuru#Naivasha`,

    registrationSuccess: (name) => `Your profile has been created successfully ${name}.\n\nSMS details#levelOfEducation#profession#maritalStatus#religion#ethnicity to 22141.\nE.g. details#diploma#driver#single#christian#mijikenda`,

    detailsNotProvided: `You were registered for dating with your initial details.\n\nTo search for a MPENZI, SMS match#age#town to 22141\nE.g., match#23-25#Nairobi`,

    detailsProvided: `This is the last stage of registration. SMS a brief description of yourself to 22141 starting with the word MYSELF.\nE.g., MYSELF chocolate, lovely, sexy etc.`,

    selfDescriptionSuccess: `You are now registered for dating. To search for a MPENZI, SMS match#age#town to 22141 and meet the person of your dreams.\nE.g., match#23-25#Kisumu`,

    matchFound: (count, gender) => `We have ${count} ${gender} who match your choice! We will send you details of 3 of them shortly. To get more details about a ${gender.slice(0, -1)}, SMS her number e.g., 0722010203 to 22141`,

    matchList: (matches) => {
      return matches.map(m => `${m.name} aged ${m.age}, ${m.phone}`).join('\n') + 
             '\n\nSend NEXT to 22141 to receive details of the remaining ladies';
    },

    nextMatches: (matches) => {
      return matches.map(m => `${m.name} aged ${m.age}, ${m.phone}`).join('\n') + 
             '\n\nSend NEXT to 22141 to receive details of the remaining ladies';
    },

    userDetails: (user) => `${user.name} aged ${user.age}, ${user.county || 'N/A'} County, ${user.town || 'N/A'} town,\n${user.education || 'N/A'}, ${user.profession || 'N/A'}, ${user.marital_status || 'N/A'}, ${user.religion || 'N/A'}, ${user.ethnicity || 'N/A'}.\n\nSend DESCRIBE ${user.phone} to get more details about ${user.name}.`,

    interestNotification: (fromUser, toUser) => `Hi ${toUser.name}, a ${fromUser.gender || 'man'} called ${fromUser.name} is interested in you and requested your details.\nHe is aged ${fromUser.age} based in ${fromUser.town || 'N/A'}.\n\nDo you want to know more about him? Send YES to 22141`,

    userDescription: (user) => `${user.name} describes themselves as ${user.description || 'Not provided'}`,

    consentConfirmation: (fromUser) => `${fromUser.name} aged ${fromUser.age}, ${fromUser.county || 'N/A'} County, ${fromUser.town || 'N/A'} town,\n${fromUser.education || 'N/A'}, ${fromUser.profession || 'N/A'}, ${fromUser.marital_status || 'N/A'}, ${fromUser.religion || 'N/A'}, ${fromUser.ethnicity || 'N/A'}.\n\nSend DESCRIBE ${fromUser.phone} to get more details about ${fromUser.name}.`,

    interestSent: (name) => `Your interest request has been sent successfully to ${name}.\n\nThe other member will be notified.`,

    requestAccepted: (name) => `Congratulations! You have accepted ${name}'s request.\n\nYou may now begin chatting.`
  };

  // ============================================
  // SAMPLE DATA - Gender Based (No Compatibility)
  // ============================================
  const SAMPLE_MATCHES = [];
  const SAMPLE_MALE_MATCHES = [];
  const SAMPLE_REQUESTS = [];
  const SAMPLE_MY_MATCHES = [];

  // ============================================
  // API CALL FUNCTIONS
  // ============================================
  const callApi = async (endpoint, method, body = null) => {
    try {
      const options = {
        method: method,
        headers: { 'Content-Type': 'application/json' }
      };
      if (body) {
        options.body = JSON.stringify(body);
      }
      const response = await fetch(`${API_BASE}${endpoint}`, options);
      const data = await response.json();
      console.log(`API ${method} ${endpoint}:`, data);
      return data;
    } catch (error) {
      console.error('API Error:', error);
      return null;
    }
  };

  // ============================================
  // LOAD SAVED STATE
  // ============================================
  useEffect(() => {
    try {
      const saved = localStorage.getItem('penziState');
      if (saved) {
        const parsed = JSON.parse(saved);

        if (parsed.currentUser && parsed.isLoggedIn) {
          setCurrentUser(parsed.currentUser);
          setIsLoggedIn(true);
          setAllMatches(parsed.allMatches || []);
          setIncomingRequests(parsed.incomingRequests || []);
          setMyMatches(parsed.myMatches || []);
          setChatContacts(parsed.chatContacts || []);
          setChatMessages(parsed.chatMessages || {});
          setActiveTab(parsed.activeTab || 'discover');
          setMyPhone(parsed.myPhone || '0712345678');
          setActivationDone(true);
          setShowWelcomeBack(true);
          setShowMainMenu(true);
          setMatchOffset(parsed.matchOffset || 0);
          setTotalMatches(parsed.totalMatches || 0);
          setSmsConversation(parsed.smsConversation || []);

          setTimeout(() => {
            addNotification(`👋 Welcome back, ${parsed.currentUser.name}!`);
          }, 500);

          setIsFirstTimeUser(false);
        } else {
          setCurrentStep(parsed.currentStep || 0);
          setCompletedSteps(new Set(parsed.completedSteps || []));
          setPhoneNumber(parsed.phoneNumber || '');
          setActivationDone(parsed.activationDone || false);
          setMyPhone(parsed.myPhone || '0712345678');
          setSmsConversation(parsed.smsConversation || []);
          if (parsed.currentUser) {
            setCurrentUser(parsed.currentUser);
          }
          setIsFirstTimeUser(false);
        }
      }
    } catch (e) {
      console.warn('Could not load saved state:', e);
      setIsFirstTimeUser(true);
    }
  }, []);

  // ============================================
  // SESSION INACTIVITY (5 MINUTES)
  // ============================================
  useEffect(() => {
    let inactivityTimer;

    const resetTimer = () => {
      if (inactivityTimer) clearTimeout(inactivityTimer);

      // Only set timeout if logged in or activated
      if (isLoggedIn || activationDone) {
        inactivityTimer = setTimeout(() => {
          handleLogout();
          addNotification('Session expired due to inactivity.', 'error');
        }, 5 * 60 * 1000); // 5 minutes
      }
    };

    const events = ['mousemove', 'keydown', 'click', 'scroll', 'touchstart'];
    events.forEach(evt => window.addEventListener(evt, resetTimer));
    resetTimer();

    return () => {
      if (inactivityTimer) clearTimeout(inactivityTimer);
      events.forEach(evt => window.removeEventListener(evt, resetTimer));
    };
  }, [isLoggedIn, activationDone]);

  // ============================================
  // SAVE STATE
  // ============================================
  useEffect(() => {
    try {
      const stateToSave = {
        currentStep,
        completedSteps: Array.from(completedSteps),
        currentUser,
        isLoggedIn,
        phoneNumber,
        activationDone,
        allMatches,
        incomingRequests,
        myMatches,
        chatContacts,
        chatMessages,
        activeTab,
        myPhone,
        showMainMenu,
        searchCriteria,
        matchOffset,
        totalMatches,
        smsConversation
      };
      localStorage.setItem('penziState', JSON.stringify(stateToSave));
    } catch (e) {
      console.warn('Could not save state:', e);
    }
  }, [currentStep, completedSteps, currentUser, isLoggedIn, phoneNumber, activationDone, allMatches, incomingRequests, myMatches, chatContacts, chatMessages, activeTab, myPhone, showMainMenu, searchCriteria, matchOffset, totalMatches, smsConversation]);

  // ============================================
  // UPDATE STATS
  // ============================================
  useEffect(() => {
    setStats({
      totalMatches: allMatches.length + myMatches.length,
      pendingRequests: incomingRequests.filter(r => r.status === 'pending').length,
      acceptedMatches: myMatches.length,
      unreadMessages: chatContacts.reduce((sum, c) => sum + (c.unread || 0), 0)
    });
  }, [allMatches, incomingRequests, myMatches, chatContacts]);

  // ============================================
  // CHECK SERVER
  // ============================================
  useEffect(() => {
    checkServer();
  }, []);

  const checkServer = async () => {
    try {
      const response = await fetch(`${API_BASE}/activate`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ penzi: 'penzi' })
      });
      if (response.ok || response.status === 400 || response.status === 405) {
        setServerStatus('connected');
      } else {
        setServerStatus('error');
      }
    } catch (error) {
      setServerStatus('error');
    }
  };

  // ============================================
  // OTP TIMER EFFECTS
  // ============================================
  useEffect(() => {
    let interval;
    if (otpSent && otpTimerSeconds > 0) {
      interval = setInterval(() => {
        setOtpTimerSeconds(s => {
          if (s <= 1) { clearInterval(interval); return 0; }
          return s - 1;
        });
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [otpSent, otpTimerSeconds]);

  useEffect(() => {
    let interval;
    if (otpSent && !canResendOtp && resendCountdown > 0) {
      interval = setInterval(() => {
        setResendCountdown(s => {
          if (s <= 1) { clearInterval(interval); setCanResendOtp(true); return 0; }
          return s - 1;
        });
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [otpSent, canResendOtp, resendCountdown]);

  // Activation auto-redirect
  useEffect(() => {
    let interval;
    if (activationRedirecting && activationCountdown > 0) {
      interval = setInterval(() => {
        setActivationCountdown(s => {
          if (s <= 0.5) { 
            clearInterval(interval); 
            setActivationDone(true);
            setCurrentStep(1);
            setActivationRedirecting(false);
            return 0; 
          }
          return s - 0.5;
        });
      }, 500);
    }
    return () => clearInterval(interval);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activationRedirecting, activationCountdown]);

  // Success screen auto-redirect
  useEffect(() => {
    let interval;
    if (successRedirecting && successCountdown > 0) {
      interval = setInterval(() => {
        setSuccessCountdown(s => {
          if (s <= 1) {
            clearInterval(interval);
            setShowSuccessScreen(false);
            setSuccessRedirecting(false);
            if (currentStep < 3) {
              setCurrentStep(prev => prev + 1);
            } else {
              setIsLoggedIn(true);
              setShowMainMenu(true);
            }
            return 0;
          }
          return s - 1;
        });
      }, 1000);
    }
    return () => clearInterval(interval);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [successRedirecting, successCountdown, currentStep]);

  // ============================================
  // LOGIN HELPER — Kenyan phone validator
  // ============================================
  const validateKenyanPhone = (phone) => {
    const cleaned = phone.replace(/[\s\-\(\)\+]/g, '');
    const patterns = [/^07\d{8}$/, /^01\d{8}$/, /^2547\d{8}$/, /^2541\d{8}$/, /^7\d{8}$/, /^1\d{8}$/];
    return patterns.some(p => p.test(cleaned));
  };

  // ============================================
  // LOGIN — Send OTP
  // ============================================
  const handleSendOtp = async () => {
    setOtpError('');
    setOtpSuccess('');
    const trimmedPhone = loginPhone.trim();
    if (!trimmedPhone) { setOtpError('Please enter your phone number.'); return; }
    if (!validateKenyanPhone(trimmedPhone)) {
      setOtpError('Invalid Kenyan phone number. Use format: 0712345678');
      return;
    }
    setIsSendingOtp(true);
    try {
      const res = await fetch(`${API_BASE}/send-otp`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ phone_number: trimmedPhone })
      });
      const data = await res.json();
      if (data.status === 'success') {
        setOtpSent(true);
        setOtpTimerSeconds(120);
        setCanResendOtp(false);
        setResendCountdown(30);
        setLoginOtp('');
        setOtpSuccess('OTP sent successfully!');

        // Show OTP popup for 4 seconds
        if (data.data && data.data.otp) {
          setPopupOtp(data.data.otp);
          setTimeout(() => {
            setPopupOtp('');
          }, 4000);
        }
      } else {
        setOtpError(data.message || 'Failed to send OTP.');
      }
    } catch {
      setOtpError('Network error. Please check your connection.');
    } finally {
      setIsSendingOtp(false);
    }
  };

  // ============================================
  // LOGIN — Verify OTP
  // ============================================
  const handleVerifyOtp = async () => {
    setOtpError('');
    if (!loginOtp.trim() || loginOtp.trim().length !== 6) {
      setOtpError('Please enter the 6-digit OTP.');
      return;
    }
    setIsVerifyingOtp(true);
    try {
      const res = await fetch(`${API_BASE}/verify-otp`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ phone_number: loginPhone.trim(), otp: loginOtp.trim() })
      });
      const data = await res.json();
      if (data.status === 'success') {
        localStorage.setItem('penzi_session', data.data.session_token);
        const userData = data.data.user;
        if (userData) {
          const user = {
            phone: userData.phone || loginPhone.trim(),
            name: userData.name,
            age: userData.age,
            gender: userData.gender,
            town: userData.town,
            county: userData.county,
            profession: userData.profession,
            education: userData.education,
            description: userData.description
          };
          setCurrentUser(user);
          setMyPhone(user.phone);
          setActivationDone(true);
          setIsLoggedIn(true);
          setShowMainMenu(true);
          setIsFirstTimeUser(false);
          addNotification(`💖 Welcome back, ${user.name}!`);
        } else {
          // Phone verified but not registered — go to activation
          setMyPhone(loginPhone.trim());
          setCurrentView('activation');
          addNotification('📝 Please register to continue.');
        }
      } else {
        setOtpError(data.message || 'Invalid OTP.');
      }
    } catch {
      setOtpError('Network error. Please try again.');
    } finally {
      setIsVerifyingOtp(false);
    }
  };

  // ============================================
